		else

		{

			ptr++;

			switch (*ptr)

			{

				case 'b': *ptr2++='\b';	break;

				case 'f': *ptr2++='\f';	break;

				case 'n': *ptr2++='\n';	break;

				case 'r': *ptr2++='\r';	break;

				case 't': *ptr2++='\t';	break;

