	if (!str)

	{

		if (p)	out=ensure(p,3);

		else	out=(char*)cJSON_malloc(3);

		if (!out) return 0;

		strcpy(out,"\"\"");

		return out;

	}



	for (ptr=str;*ptr;ptr++) flag|=((*ptr>0 && *ptr<32)||(*ptr=='\"')||(*ptr=='\\'))?1:0;

	if (!flag)

	{

		len=ptr-str;

		if (p) out=ensure(p,len+3);

		else		out=(char*)cJSON_malloc(len+3);

		if (!out) return 0;

		ptr2=out;*ptr2++='\"';

		strcpy(ptr2,str);

		ptr2[len]='\"';

		ptr2[len+1]=0;

		return out;

