	{ .index = MSR_IA32_LASTBRANCHFROMIP,		.always = false },

	{ .index = MSR_IA32_LASTBRANCHTOIP,		.always = false },

	{ .index = MSR_IA32_LASTINTFROMIP,		.always = false },

	{ .index = MSR_IA32_LASTINTTOIP,		.always = false },

	{ .index = MSR_INVALID,				.always = false },

};



