    DSA_HALF_SIZE = 20,   /* r and s size  */

    DSA_SIG_SIZE  = 40    /* signature size */

};







int wc_InitDsaKey(DsaKey* key)

{

    if (key == NULL)

        return BAD_FUNC_ARG;



    key->type = -1;  /* haven't decided yet */

    key->heap = NULL;



    return mp_init_multi(

        /* public  alloc parts */

        &key->p,

        &key->q,

        &key->g,

        &key->y,



        /* private alloc parts */

        &key->x,

        NULL

    );

}





int wc_InitDsaKey_h(DsaKey* key, void* h)

{

    int ret = wc_InitDsaKey(key);

    if (ret == 0)

        key->heap = h;



    return ret;

}





void wc_FreeDsaKey(DsaKey* key)

{

    if (key == NULL)

        return;



    if (key->type == DSA_PRIVATE)

        mp_forcezero(&key->x);



    mp_clear(&key->x);

    mp_clear(&key->y);

    mp_clear(&key->g);

    mp_clear(&key->q);

    mp_clear(&key->p);

}





/* validate that (L,N) match allowed sizes from FIPS 186-4, Section 4.2.

 * modLen - represents L, the size of p (prime modulus) in bits

 * divLen - represents N, the size of q (prime divisor) in bits

 * return 0 on success, -1 on error */

static int CheckDsaLN(int modLen, int divLen)

{

    int ret = -1;



    switch (modLen) {

        case 1024:

            if (divLen == 160)

                ret = 0;

            break;

        case 2048:

            if (divLen == 224 || divLen == 256)

                ret = 0;

            break;

        case 3072:

            if (divLen == 256)

                ret = 0;

            break;

        default:

            break;

    }



    return ret;

}





#ifdef WOLFSSL_KEY_GEN



/* Create DSA key pair (&dsa->x, &dsa->y)

 *

 * Based on NIST FIPS 186-4,

 * "B.1.1 Key Pair Generation Using Extra Random Bits"

 *

 * rng - pointer to initialized WC_RNG structure

 * dsa - pointer to initialized DsaKey structure, will hold generated key

 *

 * return 0 on success, negative on error */

int wc_MakeDsaKey(WC_RNG *rng, DsaKey *dsa)

{

    byte* cBuf;

    int qSz, pSz, cSz, err;

    mp_int tmpQ;



    if (rng == NULL || dsa == NULL)

        return BAD_FUNC_ARG;



    qSz = mp_unsigned_bin_size(&dsa->q);

    pSz = mp_unsigned_bin_size(&dsa->p);



    /* verify (L,N) pair bit lengths */

    if (CheckDsaLN(pSz * WOLFSSL_BIT_SIZE, qSz * WOLFSSL_BIT_SIZE) != 0)

        return BAD_FUNC_ARG;



    /* generate extra 64 bits so that bias from mod function is negligible */

    cSz = qSz + (64 / WOLFSSL_BIT_SIZE);

    cBuf = (byte*)XMALLOC(cSz, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

    if (cBuf == NULL) {

        return MEMORY_E;

    }



    if ((err = mp_init_multi(&dsa->x, &dsa->y, &tmpQ, NULL, NULL, NULL))

                   != MP_OKAY) {

        XFREE(cBuf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

        return err;

    }



    do {

        /* generate N+64 bits (c) from RBG into &dsa->x, making sure positive.

         * Hash_DRBG uses SHA-256 which matches maximum

         * requested_security_strength of (L,N) */

        err = wc_RNG_GenerateBlock(rng, cBuf, cSz);

        if (err != MP_OKAY) {

            mp_clear(&dsa->x);

            mp_clear(&dsa->y);

            mp_clear(&tmpQ);

            XFREE(cBuf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

            return err;

        }



        err = mp_read_unsigned_bin(&dsa->x, cBuf, cSz);

        if (err != MP_OKAY) {

            mp_clear(&dsa->x);

            mp_clear(&dsa->y);

            mp_clear(&tmpQ);

            XFREE(cBuf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

            return err;

        }

    } while (mp_cmp_d(&dsa->x, 1) != MP_GT);



    XFREE(cBuf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);



    /* tmpQ = q - 1 */

    if (err == MP_OKAY)

        err = mp_copy(&dsa->q, &tmpQ);



    if (err == MP_OKAY)

        err = mp_sub_d(&tmpQ, 1, &tmpQ);



    /* x = c mod (q-1), &dsa->x holds c */

    if (err == MP_OKAY)

        err = mp_mod(&dsa->x, &tmpQ, &dsa->x);



    /* x = c mod (q-1) + 1 */

    if (err == MP_OKAY)

        err = mp_add_d(&dsa->x, 1, &dsa->x);



    /* public key : y = g^x mod p */

    if (err == MP_OKAY)

        err = mp_exptmod_ex(&dsa->g, &dsa->x, dsa->q.used, &dsa->p, &dsa->y);



    if (err == MP_OKAY)

        dsa->type = DSA_PRIVATE;



    if (err != MP_OKAY) {

        mp_clear(&dsa->x);

        mp_clear(&dsa->y);

    }

    mp_clear(&tmpQ);



    return err;

}





/* modulus_size in bits */

int wc_MakeDsaParameters(WC_RNG *rng, int modulus_size, DsaKey *dsa)

{

    mp_int  tmp, tmp2;

    int     err, msize, qsize,

            loop_check_prime = 0,

            check_prime = MP_NO;

    unsigned char   *buf;



    if (rng == NULL || dsa == NULL)

        return BAD_FUNC_ARG;



    /* set group size in bytes from modulus size

     * FIPS 186-4 defines valid values (1024, 160) (2048, 256) (3072, 256)

     */

    switch (modulus_size) {

        case 1024:

            qsize = 20;

            break;

        case 2048:

        case 3072:

            qsize = 32;

            break;

        default:

            return BAD_FUNC_ARG;

    }



    /* modulus size in bytes */

    msize = modulus_size / WOLFSSL_BIT_SIZE;



    /* allocate ram */

    buf = (unsigned char *)XMALLOC(msize - qsize,

                                   dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

    if (buf == NULL) {

        return MEMORY_E;

    }



    /* make a random string that will be multplied against q */

    err = wc_RNG_GenerateBlock(rng, buf, msize - qsize);

    if (err != MP_OKAY) {

        XFREE(buf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

        return err;

    }



    /* force magnitude */

    buf[0] |= 0xC0;



    /* force even */

    buf[msize - qsize - 1] &= ~1;



    if (mp_init_multi(&tmp2, &dsa->p, &dsa->q, 0, 0, 0) != MP_OKAY) {

        mp_clear(&dsa->q);

        XFREE(buf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

        return MP_INIT_E;

    }



    err = mp_read_unsigned_bin(&tmp2, buf, msize - qsize);

    if (err != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp2);

        XFREE(buf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);

        return err;

    }

    XFREE(buf, dsa->heap, DYNAMIC_TYPE_TMP_BUFFER);



    /* make our prime q */

    err = mp_rand_prime(&dsa->q, qsize, rng, NULL);

    if (err != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp2);

        return err;

    }



    /* p = random * q */

    err = mp_mul(&dsa->q, &tmp2, &dsa->p);

    if (err != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp2);

        return err;

    }



    /* p = random * q + 1, so q is a prime divisor of p-1 */

    err = mp_add_d(&dsa->p, 1, &dsa->p);

    if (err != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp2);

        return err;

    }



    if (mp_init(&tmp) != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp2);

        return MP_INIT_E;

    }



    /* tmp = 2q  */

    err = mp_add(&dsa->q, &dsa->q, &tmp);

    if (err != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp);

        mp_clear(&tmp2);

        return err;

    }



    /* loop until p is prime */

    while (check_prime == MP_NO) {

        err = mp_prime_is_prime_ex(&dsa->p, 8, &check_prime, rng);

        if (err != MP_OKAY) {

            mp_clear(&dsa->q);

            mp_clear(&dsa->p);

            mp_clear(&tmp);

            mp_clear(&tmp2);

            return err;

        }



        if (check_prime != MP_YES) {

            /* p += 2q */

            err = mp_add(&tmp, &dsa->p, &dsa->p);

            if (err != MP_OKAY) {

                mp_clear(&dsa->q);

                mp_clear(&dsa->p);

                mp_clear(&tmp);

                mp_clear(&tmp2);

                return err;

            }



            loop_check_prime++;

        }

    }



    /* tmp2 += (2*loop_check_prime)

     * to have p = (q * tmp2) + 1 prime

     */

    if (loop_check_prime) {

        err = mp_add_d(&tmp2, 2*loop_check_prime, &tmp2);

        if (err != MP_OKAY) {

            mp_clear(&dsa->q);

            mp_clear(&dsa->p);

            mp_clear(&tmp);

            mp_clear(&tmp2);

            return err;

        }

    }



    if (mp_init(&dsa->g) != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp);

        mp_clear(&tmp2);

        return MP_INIT_E;

    }



    /* find a value g for which g^tmp2 != 1 */

    if (mp_set(&dsa->g, 1) != MP_OKAY) {

        mp_clear(&dsa->q);

        mp_clear(&dsa->p);

        mp_clear(&tmp);

        mp_clear(&tmp2);

        return MP_INIT_E;

    }



    do {

        err = mp_add_d(&dsa->g, 1, &dsa->g);

        if (err != MP_OKAY) {

            mp_clear(&dsa->q);

            mp_clear(&dsa->p);

            mp_clear(&dsa->g);

            mp_clear(&tmp);

            mp_clear(&tmp2);

            return err;

        }



        err = mp_exptmod(&dsa->g, &tmp2, &dsa->p, &tmp);

        if (err != MP_OKAY) {

            mp_clear(&dsa->q);

            mp_clear(&dsa->p);

            mp_clear(&dsa->g);

            mp_clear(&tmp);

            mp_clear(&tmp2);

            return err;

        }



    } while (mp_cmp_d(&tmp, 1) == MP_EQ);



    /* at this point tmp generates a group of order q mod p */

    mp_exch(&tmp, &dsa->g);



    mp_clear(&tmp);

    mp_clear(&tmp2);



    return MP_OKAY;

}

