 * gSz  - length of g

 *

 * returns 0 on success, negative upon failure

 */

int wc_DsaImportParamsRaw(DsaKey* dsa, const char* p, const char* q,

                          const char* g)

{

    return _DsaImportParamsRaw(dsa, p, q, g, 1, NULL);

}





