#if HAVE_LIBGCRYPT

static int network_config_set_security_level (oconfig_item_t *ci, /* {{{ */

    int *retval)

{

  char *str;

  if ((ci->values_num != 1)

      || (ci->values[0].type != OCONFIG_TYPE_STRING))

  {

