/* VRRP FSM (Finite State Machine) design.

 *

 * The state transition diagram implemented is :

 *

 *                         +---------------+

 *        +----------------|               |----------------+

 *        |                |     Fault     |                |

 *        |  +------------>|               |<------------+  |

 *        |  |             +---------------+             |  |

 *        |  |                     |                     |  |

 *        |  |                     V                     |  |

 *        |  |             +---------------+             |  |

 *        |  |  +--------->|               |<---------+  |  |

 *        |  |  |          |  Initialize   |          |  |  |

 *        |  |  |  +-------|               |-------+  |  |  |

 *        |  |  |  |       +---------------+       |  |  |  |

 *        |  |  |  |                               |  |  |  |

 *        V  |  |  V                               V  |  |  V

 *     +---------------+                       +---------------+

 *     |               |---------------------->|               |

 *     |    Master     |                       |    Backup     |

 *     |               |<----------------------|               |

 *     +---------------+                       +---------------+

 */



static int vrrp_script_child_thread(thread_t *);

static int vrrp_script_thread(thread_t *);

