static void brcmf_deinit_priv_mem(struct brcmf_cfg80211_info *cfg)

{

	kfree(cfg->conf);

	cfg->conf = NULL;

	kfree(cfg->extra_buf);

	cfg->extra_buf = NULL;

	kfree(cfg->wowl.nd);

	cfg->wowl.nd = NULL;

	kfree(cfg->wowl.nd_info);

	cfg->wowl.nd_info = NULL;

	kfree(cfg->escan_info.escan_buf);

	cfg->escan_info.escan_buf = NULL;

}



static s32 brcmf_init_priv_mem(struct brcmf_cfg80211_info *cfg)

{

	cfg->conf = kzalloc(sizeof(*cfg->conf), GFP_KERNEL);

	if (!cfg->conf)

		goto init_priv_mem_out;

	cfg->extra_buf = kzalloc(WL_EXTRA_BUF_MAX, GFP_KERNEL);

	if (!cfg->extra_buf)

		goto init_priv_mem_out;

	cfg->wowl.nd = kzalloc(sizeof(*cfg->wowl.nd) + sizeof(u32), GFP_KERNEL);

	if (!cfg->wowl.nd)

		goto init_priv_mem_out;

	cfg->wowl.nd_info = kzalloc(sizeof(*cfg->wowl.nd_info) +

				    sizeof(struct cfg80211_wowlan_nd_match *),

				    GFP_KERNEL);

	if (!cfg->wowl.nd_info)

		goto init_priv_mem_out;

	cfg->escan_info.escan_buf = kzalloc(BRCMF_ESCAN_BUF_SIZE, GFP_KERNEL);

	if (!cfg->escan_info.escan_buf)

		goto init_priv_mem_out;



	return 0;



init_priv_mem_out:

	brcmf_deinit_priv_mem(cfg);



	return -ENOMEM;

}



static s32 wl_init_priv(struct brcmf_cfg80211_info *cfg)

{

	s32 err = 0;



	cfg->scan_request = NULL;

	cfg->pwr_save = true;

	cfg->active_scan = true;	/* we do active scan per default */

	cfg->dongle_up = false;		/* dongle is not up yet */

	err = brcmf_init_priv_mem(cfg);

	if (err)

		return err;

	brcmf_register_event_handlers(cfg);

	mutex_init(&cfg->usr_sync);

	brcmf_init_escan(cfg);

	brcmf_init_conf(cfg->conf);

	init_completion(&cfg->vif_disabled);

	return err;

}



static void wl_deinit_priv(struct brcmf_cfg80211_info *cfg)

{

	cfg->dongle_up = false;	/* dongle down */

	brcmf_abort_scanning(cfg);

	brcmf_deinit_priv_mem(cfg);

}



static void init_vif_event(struct brcmf_cfg80211_vif_event *event)

{

	init_waitqueue_head(&event->vif_wq);

	spin_lock_init(&event->vif_event_lock);

}



static s32 brcmf_dongle_roam(struct brcmf_if *ifp)

{

	s32 err;

	u32 bcn_timeout;

	__le32 roamtrigger[2];

	__le32 roam_delta[2];



	/* Configure beacon timeout value based upon roaming setting */

	if (ifp->drvr->settings->roamoff)

		bcn_timeout = BRCMF_DEFAULT_BCN_TIMEOUT_ROAM_OFF;

	else

		bcn_timeout = BRCMF_DEFAULT_BCN_TIMEOUT_ROAM_ON;

	err = brcmf_fil_iovar_int_set(ifp, "bcn_timeout", bcn_timeout);

	if (err) {

		brcmf_err("bcn_timeout error (%d)\n", err);

		goto roam_setup_done;

	}



	/* Enable/Disable built-in roaming to allow supplicant to take care of

	 * roaming.

	 */

	brcmf_dbg(INFO, "Internal Roaming = %s\n",

		  ifp->drvr->settings->roamoff ? "Off" : "On");

	err = brcmf_fil_iovar_int_set(ifp, "roam_off",

				      ifp->drvr->settings->roamoff);

	if (err) {

		brcmf_err("roam_off error (%d)\n", err);

		goto roam_setup_done;

	}



	roamtrigger[0] = cpu_to_le32(WL_ROAM_TRIGGER_LEVEL);

	roamtrigger[1] = cpu_to_le32(BRCM_BAND_ALL);

	err = brcmf_fil_cmd_data_set(ifp, BRCMF_C_SET_ROAM_TRIGGER,

				     (void *)roamtrigger, sizeof(roamtrigger));

	if (err) {

		brcmf_err("WLC_SET_ROAM_TRIGGER error (%d)\n", err);

		goto roam_setup_done;

	}



	roam_delta[0] = cpu_to_le32(WL_ROAM_DELTA);

	roam_delta[1] = cpu_to_le32(BRCM_BAND_ALL);

	err = brcmf_fil_cmd_data_set(ifp, BRCMF_C_SET_ROAM_DELTA,

				     (void *)roam_delta, sizeof(roam_delta));

	if (err) {

		brcmf_err("WLC_SET_ROAM_DELTA error (%d)\n", err);

		goto roam_setup_done;

	}



roam_setup_done:

	return err;

}



static s32

brcmf_dongle_scantime(struct brcmf_if *ifp)

{

	s32 err = 0;



	err = brcmf_fil_cmd_int_set(ifp, BRCMF_C_SET_SCAN_CHANNEL_TIME,

				    BRCMF_SCAN_CHANNEL_TIME);

	if (err) {

		brcmf_err("Scan assoc time error (%d)\n", err);

		goto dongle_scantime_out;

	}

	err = brcmf_fil_cmd_int_set(ifp, BRCMF_C_SET_SCAN_UNASSOC_TIME,

				    BRCMF_SCAN_UNASSOC_TIME);

	if (err) {

		brcmf_err("Scan unassoc time error (%d)\n", err);

		goto dongle_scantime_out;

	}



	err = brcmf_fil_cmd_int_set(ifp, BRCMF_C_SET_SCAN_PASSIVE_TIME,

				    BRCMF_SCAN_PASSIVE_TIME);

	if (err) {

		brcmf_err("Scan passive time error (%d)\n", err);

		goto dongle_scantime_out;

	}



dongle_scantime_out:

	return err;

}



static void brcmf_update_bw40_channel_flag(struct ieee80211_channel *channel,

					   struct brcmu_chan *ch)

{

	u32 ht40_flag;



	ht40_flag = channel->flags & IEEE80211_CHAN_NO_HT40;

	if (ch->sb == BRCMU_CHAN_SB_U) {

		if (ht40_flag == IEEE80211_CHAN_NO_HT40)

			channel->flags &= ~IEEE80211_CHAN_NO_HT40;

		channel->flags |= IEEE80211_CHAN_NO_HT40PLUS;

	} else {

		/* It should be one of

		 * IEEE80211_CHAN_NO_HT40 or

		 * IEEE80211_CHAN_NO_HT40PLUS

		 */

		channel->flags &= ~IEEE80211_CHAN_NO_HT40;

		if (ht40_flag == IEEE80211_CHAN_NO_HT40)

			channel->flags |= IEEE80211_CHAN_NO_HT40MINUS;

	}

}



static int brcmf_construct_chaninfo(struct brcmf_cfg80211_info *cfg,

				    u32 bw_cap[])

{

	struct brcmf_if *ifp = netdev_priv(cfg_to_ndev(cfg));

	struct ieee80211_supported_band *band;

	struct ieee80211_channel *channel;

	struct wiphy *wiphy;

	struct brcmf_chanspec_list *list;

	struct brcmu_chan ch;

	int err;

	u8 *pbuf;

	u32 i, j;

	u32 total;

	u32 chaninfo;



	pbuf = kzalloc(BRCMF_DCMD_MEDLEN, GFP_KERNEL);



	if (pbuf == NULL)

		return -ENOMEM;



	list = (struct brcmf_chanspec_list *)pbuf;



	err = brcmf_fil_iovar_data_get(ifp, "chanspecs", pbuf,

				       BRCMF_DCMD_MEDLEN);

	if (err) {

		brcmf_err("get chanspecs error (%d)\n", err);

		goto fail_pbuf;

	}



	wiphy = cfg_to_wiphy(cfg);

	band = wiphy->bands[NL80211_BAND_2GHZ];

	if (band)

		for (i = 0; i < band->n_channels; i++)

			band->channels[i].flags = IEEE80211_CHAN_DISABLED;

	band = wiphy->bands[NL80211_BAND_5GHZ];

	if (band)

		for (i = 0; i < band->n_channels; i++)

			band->channels[i].flags = IEEE80211_CHAN_DISABLED;



	total = le32_to_cpu(list->count);

	for (i = 0; i < total; i++) {

		ch.chspec = (u16)le32_to_cpu(list->element[i]);

		cfg->d11inf.decchspec(&ch);



		if (ch.band == BRCMU_CHAN_BAND_2G) {

			band = wiphy->bands[NL80211_BAND_2GHZ];

		} else if (ch.band == BRCMU_CHAN_BAND_5G) {

			band = wiphy->bands[NL80211_BAND_5GHZ];

		} else {

			brcmf_err("Invalid channel Spec. 0x%x.\n", ch.chspec);

			continue;

		}

		if (!band)

			continue;

		if (!(bw_cap[band->band] & WLC_BW_40MHZ_BIT) &&

		    ch.bw == BRCMU_CHAN_BW_40)

			continue;

		if (!(bw_cap[band->band] & WLC_BW_80MHZ_BIT) &&

		    ch.bw == BRCMU_CHAN_BW_80)

			continue;



		channel = NULL;

		for (j = 0; j < band->n_channels; j++) {

			if (band->channels[j].hw_value == ch.control_ch_num) {

				channel = &band->channels[j];

				break;

			}

		}

		if (!channel) {

			/* It seems firmware supports some channel we never

			 * considered. Something new in IEEE standard?

			 */

			brcmf_err("Ignoring unexpected firmware channel %d\n",

				  ch.control_ch_num);

			continue;

		}



		if (channel->orig_flags & IEEE80211_CHAN_DISABLED)

			continue;



		/* assuming the chanspecs order is HT20,

		 * HT40 upper, HT40 lower, and VHT80.

		 */

		if (ch.bw == BRCMU_CHAN_BW_80) {

			channel->flags &= ~IEEE80211_CHAN_NO_80MHZ;

		} else if (ch.bw == BRCMU_CHAN_BW_40) {

			brcmf_update_bw40_channel_flag(channel, &ch);

		} else {

			/* enable the channel and disable other bandwidths

			 * for now as mentioned order assure they are enabled

			 * for subsequent chanspecs.

			 */

			channel->flags = IEEE80211_CHAN_NO_HT40 |

					 IEEE80211_CHAN_NO_80MHZ;

			ch.bw = BRCMU_CHAN_BW_20;

			cfg->d11inf.encchspec(&ch);

			chaninfo = ch.chspec;

			err = brcmf_fil_bsscfg_int_get(ifp, "per_chan_info",

						       &chaninfo);

			if (!err) {

				if (chaninfo & WL_CHAN_RADAR)

					channel->flags |=

						(IEEE80211_CHAN_RADAR |

						 IEEE80211_CHAN_NO_IR);

				if (chaninfo & WL_CHAN_PASSIVE)

					channel->flags |=

						IEEE80211_CHAN_NO_IR;

			}

		}

	}



fail_pbuf:

	kfree(pbuf);

	return err;

}



static int brcmf_enable_bw40_2g(struct brcmf_cfg80211_info *cfg)

{

	struct brcmf_if *ifp = netdev_priv(cfg_to_ndev(cfg));

	struct ieee80211_supported_band *band;

	struct brcmf_fil_bwcap_le band_bwcap;

	struct brcmf_chanspec_list *list;

	u8 *pbuf;

	u32 val;

	int err;

	struct brcmu_chan ch;

	u32 num_chan;

	int i, j;



	/* verify support for bw_cap command */

	val = WLC_BAND_5G;

	err = brcmf_fil_iovar_int_get(ifp, "bw_cap", &val);



	if (!err) {

		/* only set 2G bandwidth using bw_cap command */

		band_bwcap.band = cpu_to_le32(WLC_BAND_2G);

		band_bwcap.bw_cap = cpu_to_le32(WLC_BW_CAP_40MHZ);

		err = brcmf_fil_iovar_data_set(ifp, "bw_cap", &band_bwcap,

					       sizeof(band_bwcap));

	} else {

		brcmf_dbg(INFO, "fallback to mimo_bw_cap\n");

		val = WLC_N_BW_40ALL;

		err = brcmf_fil_iovar_int_set(ifp, "mimo_bw_cap", val);

	}



	if (!err) {

		/* update channel info in 2G band */

		pbuf = kzalloc(BRCMF_DCMD_MEDLEN, GFP_KERNEL);



		if (pbuf == NULL)

			return -ENOMEM;



		ch.band = BRCMU_CHAN_BAND_2G;

		ch.bw = BRCMU_CHAN_BW_40;

		ch.sb = BRCMU_CHAN_SB_NONE;

		ch.chnum = 0;

		cfg->d11inf.encchspec(&ch);



		/* pass encoded chanspec in query */

		*(__le16 *)pbuf = cpu_to_le16(ch.chspec);



		err = brcmf_fil_iovar_data_get(ifp, "chanspecs", pbuf,

					       BRCMF_DCMD_MEDLEN);

		if (err) {

			brcmf_err("get chanspecs error (%d)\n", err);

			kfree(pbuf);

			return err;

		}



		band = cfg_to_wiphy(cfg)->bands[NL80211_BAND_2GHZ];

		list = (struct brcmf_chanspec_list *)pbuf;

		num_chan = le32_to_cpu(list->count);

		for (i = 0; i < num_chan; i++) {

			ch.chspec = (u16)le32_to_cpu(list->element[i]);

			cfg->d11inf.decchspec(&ch);

			if (WARN_ON(ch.band != BRCMU_CHAN_BAND_2G))

				continue;

			if (WARN_ON(ch.bw != BRCMU_CHAN_BW_40))

				continue;

			for (j = 0; j < band->n_channels; j++) {

				if (band->channels[j].hw_value == ch.control_ch_num)

					break;

			}

			if (WARN_ON(j == band->n_channels))

				continue;



			brcmf_update_bw40_channel_flag(&band->channels[j], &ch);

		}

		kfree(pbuf);

	}

	return err;

}



static void brcmf_get_bwcap(struct brcmf_if *ifp, u32 bw_cap[])

{

	u32 band, mimo_bwcap;

	int err;



	band = WLC_BAND_2G;

	err = brcmf_fil_iovar_int_get(ifp, "bw_cap", &band);

	if (!err) {

		bw_cap[NL80211_BAND_2GHZ] = band;

		band = WLC_BAND_5G;

		err = brcmf_fil_iovar_int_get(ifp, "bw_cap", &band);

		if (!err) {

			bw_cap[NL80211_BAND_5GHZ] = band;

			return;

		}

		WARN_ON(1);

		return;

	}

	brcmf_dbg(INFO, "fallback to mimo_bw_cap info\n");

	mimo_bwcap = 0;

	err = brcmf_fil_iovar_int_get(ifp, "mimo_bw_cap", &mimo_bwcap);

	if (err)

		/* assume 20MHz if firmware does not give a clue */

		mimo_bwcap = WLC_N_BW_20ALL;



	switch (mimo_bwcap) {

	case WLC_N_BW_40ALL:

		bw_cap[NL80211_BAND_2GHZ] |= WLC_BW_40MHZ_BIT;

		/* fall-thru */

	case WLC_N_BW_20IN2G_40IN5G:

		bw_cap[NL80211_BAND_5GHZ] |= WLC_BW_40MHZ_BIT;

		/* fall-thru */

	case WLC_N_BW_20ALL:

		bw_cap[NL80211_BAND_2GHZ] |= WLC_BW_20MHZ_BIT;

		bw_cap[NL80211_BAND_5GHZ] |= WLC_BW_20MHZ_BIT;

		break;

	default:

		brcmf_err("invalid mimo_bw_cap value\n");

	}

}



static void brcmf_update_ht_cap(struct ieee80211_supported_band *band,

				u32 bw_cap[2], u32 nchain)

{

	band->ht_cap.ht_supported = true;

	if (bw_cap[band->band] & WLC_BW_40MHZ_BIT) {

		band->ht_cap.cap |= IEEE80211_HT_CAP_SGI_40;

		band->ht_cap.cap |= IEEE80211_HT_CAP_SUP_WIDTH_20_40;

	}

	band->ht_cap.cap |= IEEE80211_HT_CAP_SGI_20;

	band->ht_cap.cap |= IEEE80211_HT_CAP_DSSSCCK40;

	band->ht_cap.ampdu_factor = IEEE80211_HT_MAX_AMPDU_64K;

	band->ht_cap.ampdu_density = IEEE80211_HT_MPDU_DENSITY_16;

	memset(band->ht_cap.mcs.rx_mask, 0xff, nchain);

	band->ht_cap.mcs.tx_params = IEEE80211_HT_MCS_TX_DEFINED;

}



static __le16 brcmf_get_mcs_map(u32 nchain, enum ieee80211_vht_mcs_support supp)

{

	u16 mcs_map;

	int i;



	for (i = 0, mcs_map = 0xFFFF; i < nchain; i++)

		mcs_map = (mcs_map << 2) | supp;



	return cpu_to_le16(mcs_map);

}



static void brcmf_update_vht_cap(struct ieee80211_supported_band *band,

				 u32 bw_cap[2], u32 nchain, u32 txstreams,

				 u32 txbf_bfe_cap, u32 txbf_bfr_cap)

{

	__le16 mcs_map;



	/* not allowed in 2.4G band */

	if (band->band == NL80211_BAND_2GHZ)

		return;



	band->vht_cap.vht_supported = true;

	/* 80MHz is mandatory */

	band->vht_cap.cap |= IEEE80211_VHT_CAP_SHORT_GI_80;

	if (bw_cap[band->band] & WLC_BW_160MHZ_BIT) {

		band->vht_cap.cap |= IEEE80211_VHT_CAP_SUPP_CHAN_WIDTH_160MHZ;

		band->vht_cap.cap |= IEEE80211_VHT_CAP_SHORT_GI_160;

	}

	/* all support 256-QAM */

	mcs_map = brcmf_get_mcs_map(nchain, IEEE80211_VHT_MCS_SUPPORT_0_9);

	band->vht_cap.vht_mcs.rx_mcs_map = mcs_map;

	band->vht_cap.vht_mcs.tx_mcs_map = mcs_map;



	/* Beamforming support information */

	if (txbf_bfe_cap & BRCMF_TXBF_SU_BFE_CAP)

		band->vht_cap.cap |= IEEE80211_VHT_CAP_SU_BEAMFORMEE_CAPABLE;

	if (txbf_bfe_cap & BRCMF_TXBF_MU_BFE_CAP)

		band->vht_cap.cap |= IEEE80211_VHT_CAP_MU_BEAMFORMEE_CAPABLE;

	if (txbf_bfr_cap & BRCMF_TXBF_SU_BFR_CAP)

		band->vht_cap.cap |= IEEE80211_VHT_CAP_SU_BEAMFORMER_CAPABLE;

	if (txbf_bfr_cap & BRCMF_TXBF_MU_BFR_CAP)

		band->vht_cap.cap |= IEEE80211_VHT_CAP_MU_BEAMFORMER_CAPABLE;



	if ((txbf_bfe_cap || txbf_bfr_cap) && (txstreams > 1)) {

		band->vht_cap.cap |=

			(2 << IEEE80211_VHT_CAP_BEAMFORMEE_STS_SHIFT);

		band->vht_cap.cap |= ((txstreams - 1) <<

				IEEE80211_VHT_CAP_SOUNDING_DIMENSIONS_SHIFT);

		band->vht_cap.cap |=

			IEEE80211_VHT_CAP_VHT_LINK_ADAPTATION_VHT_MRQ_MFB;

	}

}



static int brcmf_setup_wiphybands(struct wiphy *wiphy)

{

	struct brcmf_cfg80211_info *cfg = wiphy_priv(wiphy);

	struct brcmf_if *ifp = netdev_priv(cfg_to_ndev(cfg));

	u32 nmode = 0;

	u32 vhtmode = 0;

	u32 bw_cap[2] = { WLC_BW_20MHZ_BIT, WLC_BW_20MHZ_BIT };

	u32 rxchain;

	u32 nchain;

	int err;

	s32 i;

	struct ieee80211_supported_band *band;

	u32 txstreams = 0;

	u32 txbf_bfe_cap = 0;

	u32 txbf_bfr_cap = 0;



	(void)brcmf_fil_iovar_int_get(ifp, "vhtmode", &vhtmode);

	err = brcmf_fil_iovar_int_get(ifp, "nmode", &nmode);

	if (err) {

		brcmf_err("nmode error (%d)\n", err);

	} else {

		brcmf_get_bwcap(ifp, bw_cap);

	}

	brcmf_dbg(INFO, "nmode=%d, vhtmode=%d, bw_cap=(%d, %d)\n",

		  nmode, vhtmode, bw_cap[NL80211_BAND_2GHZ],

		  bw_cap[NL80211_BAND_5GHZ]);



	err = brcmf_fil_iovar_int_get(ifp, "rxchain", &rxchain);

	if (err) {

		brcmf_err("rxchain error (%d)\n", err);

		nchain = 1;

	} else {

		for (nchain = 0; rxchain; nchain++)

			rxchain = rxchain & (rxchain - 1);

	}

	brcmf_dbg(INFO, "nchain=%d\n", nchain);



	err = brcmf_construct_chaninfo(cfg, bw_cap);

	if (err) {

		brcmf_err("brcmf_construct_chaninfo failed (%d)\n", err);

		return err;

	}



	if (vhtmode) {

		(void)brcmf_fil_iovar_int_get(ifp, "txstreams", &txstreams);

		(void)brcmf_fil_iovar_int_get(ifp, "txbf_bfe_cap",

					      &txbf_bfe_cap);

		(void)brcmf_fil_iovar_int_get(ifp, "txbf_bfr_cap",

					      &txbf_bfr_cap);

	}



	wiphy = cfg_to_wiphy(cfg);

	for (i = 0; i < ARRAY_SIZE(wiphy->bands); i++) {

		band = wiphy->bands[i];

		if (band == NULL)

			continue;



		if (nmode)

			brcmf_update_ht_cap(band, bw_cap, nchain);

		if (vhtmode)

			brcmf_update_vht_cap(band, bw_cap, nchain, txstreams,

					     txbf_bfe_cap, txbf_bfr_cap);

	}



	return 0;

}



static const struct ieee80211_txrx_stypes

brcmf_txrx_stypes[NUM_NL80211_IFTYPES] = {

	[NL80211_IFTYPE_STATION] = {

		.tx = 0xffff,

		.rx = BIT(IEEE80211_STYPE_ACTION >> 4) |

		      BIT(IEEE80211_STYPE_PROBE_REQ >> 4)

	},

	[NL80211_IFTYPE_P2P_CLIENT] = {

		.tx = 0xffff,

		.rx = BIT(IEEE80211_STYPE_ACTION >> 4) |

		      BIT(IEEE80211_STYPE_PROBE_REQ >> 4)

	},

	[NL80211_IFTYPE_P2P_GO] = {

		.tx = 0xffff,

		.rx = BIT(IEEE80211_STYPE_ASSOC_REQ >> 4) |

		      BIT(IEEE80211_STYPE_REASSOC_REQ >> 4) |

		      BIT(IEEE80211_STYPE_PROBE_REQ >> 4) |

		      BIT(IEEE80211_STYPE_DISASSOC >> 4) |

		      BIT(IEEE80211_STYPE_AUTH >> 4) |

		      BIT(IEEE80211_STYPE_DEAUTH >> 4) |

		      BIT(IEEE80211_STYPE_ACTION >> 4)

	},

	[NL80211_IFTYPE_P2P_DEVICE] = {

		.tx = 0xffff,

		.rx = BIT(IEEE80211_STYPE_ACTION >> 4) |

		      BIT(IEEE80211_STYPE_PROBE_REQ >> 4)

	}

};



/**

 * brcmf_setup_ifmodes() - determine interface modes and combinations.

 *

 * @wiphy: wiphy object.

 * @ifp: interface object needed for feat module api.

 *

 * The interface modes and combinations are determined dynamically here

 * based on firmware functionality.

 *

 * no p2p and no mbss:

 *

 *	#STA <= 1, #AP <= 1, channels = 1, 2 total

 *

 * no p2p and mbss:

 *

 *	#STA <= 1, #AP <= 1, channels = 1, 2 total

 *	#AP <= 4, matching BI, channels = 1, 4 total

 *

 * p2p, no mchan, and mbss:

 *

 *	#STA <= 1, #P2P-DEV <= 1, #{P2P-CL, P2P-GO} <= 1, channels = 1, 3 total

 *	#STA <= 1, #P2P-DEV <= 1, #AP <= 1, #P2P-CL <= 1, channels = 1, 4 total

 *	#AP <= 4, matching BI, channels = 1, 4 total

 *

 * p2p, mchan, and mbss:

 *

 *	#STA <= 1, #P2P-DEV <= 1, #{P2P-CL, P2P-GO} <= 1, channels = 2, 3 total

 *	#STA <= 1, #P2P-DEV <= 1, #AP <= 1, #P2P-CL <= 1, channels = 1, 4 total

 *	#AP <= 4, matching BI, channels = 1, 4 total

 */

static int brcmf_setup_ifmodes(struct wiphy *wiphy, struct brcmf_if *ifp)

{

	struct ieee80211_iface_combination *combo = NULL;

	struct ieee80211_iface_limit *c0_limits = NULL;

	struct ieee80211_iface_limit *p2p_limits = NULL;

	struct ieee80211_iface_limit *mbss_limits = NULL;

	bool mbss, p2p;

	int i, c, n_combos;



	mbss = brcmf_feat_is_enabled(ifp, BRCMF_FEAT_MBSS);

	p2p = brcmf_feat_is_enabled(ifp, BRCMF_FEAT_P2P);



	n_combos = 1 + !!p2p + !!mbss;

	combo = kcalloc(n_combos, sizeof(*combo), GFP_KERNEL);

	if (!combo)

		goto err;



	wiphy->interface_modes = BIT(NL80211_IFTYPE_STATION) |

				 BIT(NL80211_IFTYPE_ADHOC) |

				 BIT(NL80211_IFTYPE_AP);



	c = 0;

	i = 0;

	c0_limits = kcalloc(p2p ? 3 : 2, sizeof(*c0_limits), GFP_KERNEL);

	if (!c0_limits)

		goto err;

	c0_limits[i].max = 1;

	c0_limits[i++].types = BIT(NL80211_IFTYPE_STATION);

	if (p2p) {

		if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_MCHAN))

			combo[c].num_different_channels = 2;

		wiphy->interface_modes |= BIT(NL80211_IFTYPE_P2P_CLIENT) |

					  BIT(NL80211_IFTYPE_P2P_GO) |

					  BIT(NL80211_IFTYPE_P2P_DEVICE);

		c0_limits[i].max = 1;

		c0_limits[i++].types = BIT(NL80211_IFTYPE_P2P_DEVICE);

		c0_limits[i].max = 1;

		c0_limits[i++].types = BIT(NL80211_IFTYPE_P2P_CLIENT) |

				       BIT(NL80211_IFTYPE_P2P_GO);

	} else {

		c0_limits[i].max = 1;

		c0_limits[i++].types = BIT(NL80211_IFTYPE_AP);

	}

	combo[c].num_different_channels = 1;

	combo[c].max_interfaces = i;

	combo[c].n_limits = i;

	combo[c].limits = c0_limits;



	if (p2p) {

		c++;

		i = 0;

		p2p_limits = kcalloc(4, sizeof(*p2p_limits), GFP_KERNEL);

		if (!p2p_limits)

			goto err;

		p2p_limits[i].max = 1;

		p2p_limits[i++].types = BIT(NL80211_IFTYPE_STATION);

		p2p_limits[i].max = 1;

		p2p_limits[i++].types = BIT(NL80211_IFTYPE_AP);

		p2p_limits[i].max = 1;

		p2p_limits[i++].types = BIT(NL80211_IFTYPE_P2P_CLIENT);

		p2p_limits[i].max = 1;

		p2p_limits[i++].types = BIT(NL80211_IFTYPE_P2P_DEVICE);

		combo[c].num_different_channels = 1;

		combo[c].max_interfaces = i;

		combo[c].n_limits = i;

		combo[c].limits = p2p_limits;

	}



	if (mbss) {

		c++;

		i = 0;

		mbss_limits = kcalloc(1, sizeof(*mbss_limits), GFP_KERNEL);

		if (!mbss_limits)

			goto err;

		mbss_limits[i].max = 4;

		mbss_limits[i++].types = BIT(NL80211_IFTYPE_AP);

		combo[c].beacon_int_infra_match = true;

		combo[c].num_different_channels = 1;

		combo[c].max_interfaces = 4;

		combo[c].n_limits = i;

		combo[c].limits = mbss_limits;

	}



	wiphy->n_iface_combinations = n_combos;

	wiphy->iface_combinations = combo;

	return 0;



err:

	kfree(c0_limits);

	kfree(p2p_limits);

	kfree(mbss_limits);

	kfree(combo);

	return -ENOMEM;

}



