static void brcmf_wiphy_wowl_params(struct wiphy *wiphy, struct brcmf_if *ifp)

{

#ifdef CONFIG_PM

	struct brcmf_cfg80211_info *cfg = wiphy_to_cfg(wiphy);

	struct wiphy_wowlan_support *wowl;



	wowl = kmemdup(&brcmf_wowlan_support, sizeof(brcmf_wowlan_support),

		       GFP_KERNEL);

	if (!wowl) {

		brcmf_err("only support basic wowlan features\n");

		wiphy->wowlan = &brcmf_wowlan_support;

		return;

	}



	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_PNO)) {

		if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_WOWL_ND)) {

			wowl->flags |= WIPHY_WOWLAN_NET_DETECT;

			wowl->max_nd_match_sets = BRCMF_PNO_MAX_PFN_COUNT;

			init_waitqueue_head(&cfg->wowl.nd_data_wait);

		}

	}

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_WOWL_GTK)) {

		wowl->flags |= WIPHY_WOWLAN_SUPPORTS_GTK_REKEY;

		wowl->flags |= WIPHY_WOWLAN_GTK_REKEY_FAILURE;

	}



	wiphy->wowlan = wowl;

#endif

}



static int brcmf_setup_wiphy(struct wiphy *wiphy, struct brcmf_if *ifp)

{

	struct brcmf_pub *drvr = ifp->drvr;

	const struct ieee80211_iface_combination *combo;

	struct ieee80211_supported_band *band;

	u16 max_interfaces = 0;

	bool gscan;

	__le32 bandlist[3];

	u32 n_bands;

	int err, i;



	wiphy->max_scan_ssids = WL_NUM_SCAN_MAX;

	wiphy->max_scan_ie_len = BRCMF_SCAN_IE_LEN_MAX;

	wiphy->max_num_pmkids = BRCMF_MAXPMKID;



	err = brcmf_setup_ifmodes(wiphy, ifp);

	if (err)

		return err;



	for (i = 0, combo = wiphy->iface_combinations;

	     i < wiphy->n_iface_combinations; i++, combo++) {

		max_interfaces = max(max_interfaces, combo->max_interfaces);

	}



	for (i = 0; i < max_interfaces && i < ARRAY_SIZE(drvr->addresses);

	     i++) {

		u8 *addr = drvr->addresses[i].addr;



		memcpy(addr, drvr->mac, ETH_ALEN);

		if (i) {

			addr[0] |= BIT(1);

			addr[ETH_ALEN - 1] ^= i;

		}

	}

	wiphy->addresses = drvr->addresses;

	wiphy->n_addresses = i;



	wiphy->signal_type = CFG80211_SIGNAL_TYPE_MBM;

	wiphy->cipher_suites = brcmf_cipher_suites;

	wiphy->n_cipher_suites = ARRAY_SIZE(brcmf_cipher_suites);

	if (!brcmf_feat_is_enabled(ifp, BRCMF_FEAT_MFP))

		wiphy->n_cipher_suites--;

	wiphy->bss_select_support = BIT(NL80211_BSS_SELECT_ATTR_RSSI) |

				    BIT(NL80211_BSS_SELECT_ATTR_BAND_PREF) |

				    BIT(NL80211_BSS_SELECT_ATTR_RSSI_ADJUST);



	wiphy->flags |= WIPHY_FLAG_NETNS_OK |

			WIPHY_FLAG_PS_ON_BY_DEFAULT |

			WIPHY_FLAG_OFFCHAN_TX |

			WIPHY_FLAG_HAS_REMAIN_ON_CHANNEL;

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_TDLS))

		wiphy->flags |= WIPHY_FLAG_SUPPORTS_TDLS;

	if (!ifp->drvr->settings->roamoff)

		wiphy->flags |= WIPHY_FLAG_SUPPORTS_FW_ROAM;

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_FWSUP)) {

		wiphy_ext_feature_set(wiphy,

				      NL80211_EXT_FEATURE_4WAY_HANDSHAKE_STA_PSK);

		wiphy_ext_feature_set(wiphy,

				      NL80211_EXT_FEATURE_4WAY_HANDSHAKE_STA_1X);

	}

	wiphy->mgmt_stypes = brcmf_txrx_stypes;

	wiphy->max_remain_on_channel_duration = 5000;

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_PNO)) {

		gscan = brcmf_feat_is_enabled(ifp, BRCMF_FEAT_GSCAN);

		brcmf_pno_wiphy_params(wiphy, gscan);

	}

	/* vendor commands/events support */

	wiphy->vendor_commands = brcmf_vendor_cmds;

	wiphy->n_vendor_commands = BRCMF_VNDR_CMDS_LAST - 1;



	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_WOWL))

		brcmf_wiphy_wowl_params(wiphy, ifp);

	err = brcmf_fil_cmd_data_get(ifp, BRCMF_C_GET_BANDLIST, &bandlist,

				     sizeof(bandlist));

	if (err) {

		brcmf_err("could not obtain band info: err=%d\n", err);

		return err;

	}

	/* first entry in bandlist is number of bands */

	n_bands = le32_to_cpu(bandlist[0]);

	for (i = 1; i <= n_bands && i < ARRAY_SIZE(bandlist); i++) {

		if (bandlist[i] == cpu_to_le32(WLC_BAND_2G)) {

			band = kmemdup(&__wl_band_2ghz, sizeof(__wl_band_2ghz),

				       GFP_KERNEL);

			if (!band)

				return -ENOMEM;



			band->channels = kmemdup(&__wl_2ghz_channels,

						 sizeof(__wl_2ghz_channels),

						 GFP_KERNEL);

			if (!band->channels) {

				kfree(band);

				return -ENOMEM;

			}



			band->n_channels = ARRAY_SIZE(__wl_2ghz_channels);

			wiphy->bands[NL80211_BAND_2GHZ] = band;

		}

		if (bandlist[i] == cpu_to_le32(WLC_BAND_5G)) {

			band = kmemdup(&__wl_band_5ghz, sizeof(__wl_band_5ghz),

				       GFP_KERNEL);

			if (!band)

				return -ENOMEM;



			band->channels = kmemdup(&__wl_5ghz_channels,

						 sizeof(__wl_5ghz_channels),

						 GFP_KERNEL);

			if (!band->channels) {

				kfree(band);

				return -ENOMEM;

			}



			band->n_channels = ARRAY_SIZE(__wl_5ghz_channels);

			wiphy->bands[NL80211_BAND_5GHZ] = band;

		}

	}



	wiphy_read_of_freq_limits(wiphy);



	return 0;

}



static s32 brcmf_config_dongle(struct brcmf_cfg80211_info *cfg)

{

	struct net_device *ndev;

	struct wireless_dev *wdev;

	struct brcmf_if *ifp;

	s32 power_mode;

	s32 err = 0;



	if (cfg->dongle_up)

		return err;



	ndev = cfg_to_ndev(cfg);

	wdev = ndev->ieee80211_ptr;

	ifp = netdev_priv(ndev);



	/* make sure RF is ready for work */

	brcmf_fil_cmd_int_set(ifp, BRCMF_C_UP, 0);



	brcmf_dongle_scantime(ifp);



	power_mode = cfg->pwr_save ? PM_FAST : PM_OFF;

	err = brcmf_fil_cmd_int_set(ifp, BRCMF_C_SET_PM, power_mode);

	if (err)

		goto default_conf_out;

	brcmf_dbg(INFO, "power save set to %s\n",

		  (power_mode ? "enabled" : "disabled"));



	err = brcmf_dongle_roam(ifp);

	if (err)

		goto default_conf_out;

	err = brcmf_cfg80211_change_iface(wdev->wiphy, ndev, wdev->iftype,

					  NULL);

	if (err)

		goto default_conf_out;



	brcmf_configure_arp_nd_offload(ifp, true);



	cfg->dongle_up = true;

default_conf_out:



	return err;



}



static s32 __brcmf_cfg80211_up(struct brcmf_if *ifp)

{

	set_bit(BRCMF_VIF_STATUS_READY, &ifp->vif->sme_state);



	return brcmf_config_dongle(ifp->drvr->config);

}



static s32 __brcmf_cfg80211_down(struct brcmf_if *ifp)

{

	struct brcmf_cfg80211_info *cfg = ifp->drvr->config;



	/*

	 * While going down, if associated with AP disassociate

	 * from AP to save power

	 */

	if (check_vif_up(ifp->vif)) {

		brcmf_link_down(ifp->vif, WLAN_REASON_UNSPECIFIED);



		/* Make sure WPA_Supplicant receives all the event

		   generated due to DISASSOC call to the fw to keep

		   the state fw and WPA_Supplicant state consistent

		 */

		brcmf_delay(500);

	}



	brcmf_abort_scanning(cfg);

	clear_bit(BRCMF_VIF_STATUS_READY, &ifp->vif->sme_state);



	return 0;

}



s32 brcmf_cfg80211_up(struct net_device *ndev)

{

	struct brcmf_if *ifp = netdev_priv(ndev);

	struct brcmf_cfg80211_info *cfg = ifp->drvr->config;

	s32 err = 0;



	mutex_lock(&cfg->usr_sync);

	err = __brcmf_cfg80211_up(ifp);

	mutex_unlock(&cfg->usr_sync);



	return err;

}



s32 brcmf_cfg80211_down(struct net_device *ndev)

{

	struct brcmf_if *ifp = netdev_priv(ndev);

	struct brcmf_cfg80211_info *cfg = ifp->drvr->config;

	s32 err = 0;



	mutex_lock(&cfg->usr_sync);

	err = __brcmf_cfg80211_down(ifp);

	mutex_unlock(&cfg->usr_sync);



	return err;

}



enum nl80211_iftype brcmf_cfg80211_get_iftype(struct brcmf_if *ifp)

{

	struct wireless_dev *wdev = &ifp->vif->wdev;



	return wdev->iftype;

}



bool brcmf_get_vif_state_any(struct brcmf_cfg80211_info *cfg,

			     unsigned long state)

{

	struct brcmf_cfg80211_vif *vif;



	list_for_each_entry(vif, &cfg->vif_list, list) {

		if (test_bit(state, &vif->sme_state))

			return true;

	}

	return false;

}



static inline bool vif_event_equals(struct brcmf_cfg80211_vif_event *event,

				    u8 action)

{

	u8 evt_action;



	spin_lock(&event->vif_event_lock);

	evt_action = event->action;

	spin_unlock(&event->vif_event_lock);

	return evt_action == action;

}



void brcmf_cfg80211_arm_vif_event(struct brcmf_cfg80211_info *cfg,

				  struct brcmf_cfg80211_vif *vif)

{

	struct brcmf_cfg80211_vif_event *event = &cfg->vif_event;



	spin_lock(&event->vif_event_lock);

	event->vif = vif;

	event->action = 0;

	spin_unlock(&event->vif_event_lock);

}



bool brcmf_cfg80211_vif_event_armed(struct brcmf_cfg80211_info *cfg)

{

	struct brcmf_cfg80211_vif_event *event = &cfg->vif_event;

	bool armed;



	spin_lock(&event->vif_event_lock);

	armed = event->vif != NULL;

	spin_unlock(&event->vif_event_lock);



	return armed;

}



int brcmf_cfg80211_wait_vif_event(struct brcmf_cfg80211_info *cfg,

				  u8 action, ulong timeout)

{

	struct brcmf_cfg80211_vif_event *event = &cfg->vif_event;



	return wait_event_timeout(event->vif_wq,

				  vif_event_equals(event, action), timeout);

}



static s32 brcmf_translate_country_code(struct brcmf_pub *drvr, char alpha2[2],

					struct brcmf_fil_country_le *ccreq)

{

	struct brcmfmac_pd_cc *country_codes;

	struct brcmfmac_pd_cc_entry *cc;

	s32 found_index;

	int i;



	country_codes = drvr->settings->country_codes;

	if (!country_codes) {

		brcmf_dbg(TRACE, "No country codes configured for device\n");

		return -EINVAL;

	}



	if ((alpha2[0] == ccreq->country_abbrev[0]) &&

	    (alpha2[1] == ccreq->country_abbrev[1])) {

		brcmf_dbg(TRACE, "Country code already set\n");

		return -EAGAIN;

	}



	found_index = -1;

	for (i = 0; i < country_codes->table_size; i++) {

		cc = &country_codes->table[i];

		if ((cc->iso3166[0] == '\0') && (found_index == -1))

			found_index = i;

		if ((cc->iso3166[0] == alpha2[0]) &&

		    (cc->iso3166[1] == alpha2[1])) {

			found_index = i;

			break;

		}

	}

	if (found_index == -1) {

		brcmf_dbg(TRACE, "No country code match found\n");

		return -EINVAL;

	}

	memset(ccreq, 0, sizeof(*ccreq));

	ccreq->rev = cpu_to_le32(country_codes->table[found_index].rev);

	memcpy(ccreq->ccode, country_codes->table[found_index].cc,

	       BRCMF_COUNTRY_BUF_SZ);

	ccreq->country_abbrev[0] = alpha2[0];

	ccreq->country_abbrev[1] = alpha2[1];

	ccreq->country_abbrev[2] = 0;



	return 0;

}



static void brcmf_cfg80211_reg_notifier(struct wiphy *wiphy,

					struct regulatory_request *req)

{

	struct brcmf_cfg80211_info *cfg = wiphy_priv(wiphy);

	struct brcmf_if *ifp = netdev_priv(cfg_to_ndev(cfg));

	struct brcmf_fil_country_le ccreq;

	s32 err;

	int i;



	/* The country code gets set to "00" by default at boot, ignore */

	if (req->alpha2[0] == '0' && req->alpha2[1] == '0')

		return;



	/* ignore non-ISO3166 country codes */

	for (i = 0; i < sizeof(req->alpha2); i++)

		if (req->alpha2[i] < 'A' || req->alpha2[i] > 'Z') {

			brcmf_err("not an ISO3166 code (0x%02x 0x%02x)\n",

				  req->alpha2[0], req->alpha2[1]);

			return;

		}



	brcmf_dbg(TRACE, "Enter: initiator=%d, alpha=%c%c\n", req->initiator,

		  req->alpha2[0], req->alpha2[1]);



	err = brcmf_fil_iovar_data_get(ifp, "country", &ccreq, sizeof(ccreq));

	if (err) {

		brcmf_err("Country code iovar returned err = %d\n", err);

		return;

	}



	err = brcmf_translate_country_code(ifp->drvr, req->alpha2, &ccreq);

	if (err)

		return;



	err = brcmf_fil_iovar_data_set(ifp, "country", &ccreq, sizeof(ccreq));

	if (err) {

		brcmf_err("Firmware rejected country setting\n");

		return;

	}

	brcmf_setup_wiphybands(wiphy);

}



static void brcmf_free_wiphy(struct wiphy *wiphy)

{

	int i;



	if (!wiphy)

		return;



	if (wiphy->iface_combinations) {

		for (i = 0; i < wiphy->n_iface_combinations; i++)

			kfree(wiphy->iface_combinations[i].limits);

	}

	kfree(wiphy->iface_combinations);

	if (wiphy->bands[NL80211_BAND_2GHZ]) {

		kfree(wiphy->bands[NL80211_BAND_2GHZ]->channels);

		kfree(wiphy->bands[NL80211_BAND_2GHZ]);

	}

	if (wiphy->bands[NL80211_BAND_5GHZ]) {

		kfree(wiphy->bands[NL80211_BAND_5GHZ]->channels);

		kfree(wiphy->bands[NL80211_BAND_5GHZ]);

	}

#if IS_ENABLED(CONFIG_PM)

	if (wiphy->wowlan != &brcmf_wowlan_support)

		kfree(wiphy->wowlan);

#endif

	wiphy_free(wiphy);

}



struct brcmf_cfg80211_info *brcmf_cfg80211_attach(struct brcmf_pub *drvr,

						  struct device *busdev,

						  bool p2pdev_forced)

{

	struct net_device *ndev = brcmf_get_ifp(drvr, 0)->ndev;

	struct brcmf_cfg80211_info *cfg;

	struct wiphy *wiphy;

	struct cfg80211_ops *ops;

	struct brcmf_cfg80211_vif *vif;

	struct brcmf_if *ifp;

	s32 err = 0;

	s32 io_type;

	u16 *cap = NULL;



	if (!ndev) {

		brcmf_err("ndev is invalid\n");

		return NULL;

	}



	ops = kmemdup(&brcmf_cfg80211_ops, sizeof(*ops), GFP_KERNEL);

	if (!ops)

		return NULL;



	ifp = netdev_priv(ndev);

#ifdef CONFIG_PM

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_WOWL_GTK))

		ops->set_rekey_data = brcmf_cfg80211_set_rekey_data;

#endif

	wiphy = wiphy_new(ops, sizeof(struct brcmf_cfg80211_info));

	if (!wiphy) {

		brcmf_err("Could not allocate wiphy device\n");

		goto ops_out;

	}

	memcpy(wiphy->perm_addr, drvr->mac, ETH_ALEN);

	set_wiphy_dev(wiphy, busdev);



	cfg = wiphy_priv(wiphy);

	cfg->wiphy = wiphy;

	cfg->ops = ops;

	cfg->pub = drvr;

	init_vif_event(&cfg->vif_event);

	INIT_LIST_HEAD(&cfg->vif_list);



	vif = brcmf_alloc_vif(cfg, NL80211_IFTYPE_STATION);

	if (IS_ERR(vif))

		goto wiphy_out;



	vif->ifp = ifp;

	vif->wdev.netdev = ndev;

	ndev->ieee80211_ptr = &vif->wdev;

	SET_NETDEV_DEV(ndev, wiphy_dev(cfg->wiphy));



	err = wl_init_priv(cfg);

	if (err) {

		brcmf_err("Failed to init iwm_priv (%d)\n", err);

		brcmf_free_vif(vif);

		goto wiphy_out;

	}

	ifp->vif = vif;



	/* determine d11 io type before wiphy setup */

	err = brcmf_fil_cmd_int_get(ifp, BRCMF_C_GET_VERSION, &io_type);

	if (err) {

		brcmf_err("Failed to get D11 version (%d)\n", err);

		goto priv_out;

	}

	cfg->d11inf.io_type = (u8)io_type;

	brcmu_d11_attach(&cfg->d11inf);



	err = brcmf_setup_wiphy(wiphy, ifp);

	if (err < 0)

		goto priv_out;



	brcmf_dbg(INFO, "Registering custom regulatory\n");

	wiphy->reg_notifier = brcmf_cfg80211_reg_notifier;

	wiphy->regulatory_flags |= REGULATORY_CUSTOM_REG;

	wiphy_apply_custom_regulatory(wiphy, &brcmf_regdom);



	/* firmware defaults to 40MHz disabled in 2G band. We signal

	 * cfg80211 here that we do and have it decide we can enable

	 * it. But first check if device does support 2G operation.

	 */

	if (wiphy->bands[NL80211_BAND_2GHZ]) {

		cap = &wiphy->bands[NL80211_BAND_2GHZ]->ht_cap.cap;

		*cap |= IEEE80211_HT_CAP_SUP_WIDTH_20_40;

	}

	err = wiphy_register(wiphy);

	if (err < 0) {

		brcmf_err("Could not register wiphy device (%d)\n", err);

		goto priv_out;

	}



	err = brcmf_setup_wiphybands(wiphy);

	if (err) {

		brcmf_err("Setting wiphy bands failed (%d)\n", err);

		goto wiphy_unreg_out;

	}



	/* If cfg80211 didn't disable 40MHz HT CAP in wiphy_register(),

	 * setup 40MHz in 2GHz band and enable OBSS scanning.

	 */

	if (cap && (*cap & IEEE80211_HT_CAP_SUP_WIDTH_20_40)) {

		err = brcmf_enable_bw40_2g(cfg);

		if (!err)

			err = brcmf_fil_iovar_int_set(ifp, "obss_coex",

						      BRCMF_OBSS_COEX_AUTO);

		else

			*cap &= ~IEEE80211_HT_CAP_SUP_WIDTH_20_40;

	}

	/* p2p might require that "if-events" get processed by fweh. So

	 * activate the already registered event handlers now and activate

	 * the rest when initialization has completed. drvr->config needs to

	 * be assigned before activating events.

	 */

	drvr->config = cfg;

	err = brcmf_fweh_activate_events(ifp);

	if (err) {

		brcmf_err("FWEH activation failed (%d)\n", err);

		goto wiphy_unreg_out;

	}



	err = brcmf_p2p_attach(cfg, p2pdev_forced);

	if (err) {

		brcmf_err("P2P initialisation failed (%d)\n", err);

		goto wiphy_unreg_out;

	}

	err = brcmf_btcoex_attach(cfg);

	if (err) {

		brcmf_err("BT-coex initialisation failed (%d)\n", err);

		brcmf_p2p_detach(&cfg->p2p);

		goto wiphy_unreg_out;

	}

	err = brcmf_pno_attach(cfg);

	if (err) {

		brcmf_err("PNO initialisation failed (%d)\n", err);

		brcmf_btcoex_detach(cfg);

		brcmf_p2p_detach(&cfg->p2p);

		goto wiphy_unreg_out;

	}



	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_TDLS)) {

		err = brcmf_fil_iovar_int_set(ifp, "tdls_enable", 1);

		if (err) {

			brcmf_dbg(INFO, "TDLS not enabled (%d)\n", err);

			wiphy->flags &= ~WIPHY_FLAG_SUPPORTS_TDLS;

		} else {

			brcmf_fweh_register(cfg->pub, BRCMF_E_TDLS_PEER_EVENT,

					    brcmf_notify_tdls_peer_event);

		}

	}



	/* (re-) activate FWEH event handling */

	err = brcmf_fweh_activate_events(ifp);

	if (err) {

		brcmf_err("FWEH activation failed (%d)\n", err);

		goto detach;

	}



	/* Fill in some of the advertised nl80211 supported features */

	if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_SCAN_RANDOM_MAC)) {

		wiphy->features |= NL80211_FEATURE_SCHED_SCAN_RANDOM_MAC_ADDR;

#ifdef CONFIG_PM

		if (wiphy->wowlan &&

		    wiphy->wowlan->flags & WIPHY_WOWLAN_NET_DETECT)

			wiphy->features |= NL80211_FEATURE_ND_RANDOM_MAC_ADDR;

#endif

	}



	return cfg;



detach:

	brcmf_pno_detach(cfg);

	brcmf_btcoex_detach(cfg);

	brcmf_p2p_detach(&cfg->p2p);

wiphy_unreg_out:

	wiphy_unregister(cfg->wiphy);

priv_out:

	wl_deinit_priv(cfg);

	brcmf_free_vif(vif);

	ifp->vif = NULL;

wiphy_out:

	brcmf_free_wiphy(wiphy);

ops_out:

	kfree(ops);

	return NULL;

}



void brcmf_cfg80211_detach(struct brcmf_cfg80211_info *cfg)

{

	if (!cfg)

		return;



	brcmf_pno_detach(cfg);

	brcmf_btcoex_detach(cfg);

	wiphy_unregister(cfg->wiphy);

	kfree(cfg->ops);

	wl_deinit_priv(cfg);

	brcmf_free_wiphy(cfg->wiphy);

}

